export function searchAdminRegions(query, limit = 60) {
  if (!query || !query.trim()) return chinaAdminRegions.slice(0, limit);
  const keywords = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const results = [];
  for (let i = 0; i < chinaAdminRegions.length; i++) {
    const item = chinaAdminRegions[i];
    const target = (item.displayName + ' ' + (item.adcode || '') + ' ' + item.province + item.city + item.district).toLowerCase();
    const matchesAll = keywords.every(kw => target.includes(kw));
    if (matchesAll) {
      results.push(item);
      if (results.length >= limit) break;
    }
  }
  return results;
}
